package battleship.part3;
import javax.swing.*;import java.awt.*;import java.io.*;import java.net.*;
public final class Client extends JFrame {
 private final JButton[][] own=new JButton[6][6],enemy=new JButton[6][6];private final JLabel status=new JLabel("Nhập tên để kết nối");private final JTextArea log=new JTextArea();private final Board placement=new Board();private boolean horizontal=true,ready=false,opponentConnected=false;private DataInputStream in;private DataOutputStream out;private int player=-1;private String mode="SETUP";private int active=-1;private String ownState="0".repeat(36),enemyState="0".repeat(36);
 public static void main(String[] a){SwingUtilities.invokeLater(()->new Client().setVisible(true));}
 Client(){super("BattleShip Online - Phần 3");setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(900,650);setLocationRelativeTo(null);setLayout(new BorderLayout(8,8));JPanel top=new JPanel(new BorderLayout());status.setFont(new Font("SansSerif",Font.BOLD,16));top.add(status);JButton rotate=new JButton("Đổi hướng: ngang");rotate.addActionListener(e->{horizontal=!horizontal;rotate.setText("Đổi hướng: "+(horizontal?"ngang":"dọc"));});top.add(rotate,BorderLayout.EAST);add(top,BorderLayout.NORTH);
 JPanel boards=new JPanel(new GridLayout(1,2,12,0));boards.add(makeBoard("Bàn của tôi",own,true));boards.add(makeBoard("Bàn đối thủ - nhấn để bắn",enemy,false));add(boards,BorderLayout.CENTER);log.setEditable(false);log.setRows(5);add(new JScrollPane(log),BorderLayout.SOUTH);connect();}
 private JPanel makeBoard(String title,JButton[][] cells,boolean mine){JPanel p=new JPanel(new GridLayout(6,6));p.setBorder(BorderFactory.createTitledBorder(title));for(int r=0;r<6;r++)for(int c=0;c<6;c++){final int rr=r,cc=c;JButton b=new JButton(" ");b.setPreferredSize(new Dimension(55,50));b.addActionListener(e->{if(mine)place(rr,cc);else shoot(rr,cc);});cells[r][c]=b;p.add(b);}return p;}
 private void connect(){String host=JOptionPane.showInputDialog(this,"IP server","127.0.0.1");if(host==null)System.exit(0);String name=JOptionPane.showInputDialog(this,"Tên người chơi");if(name==null||name.isBlank())name="Player";try{Socket s=new Socket(host,Integer.parseInt(System.getProperty("port","5002")));in=new DataInputStream(s.getInputStream());out=new DataOutputStream(s.getOutputStream());send("NAME|"+name.replace("|",""));Thread t=new Thread(()->{try{while(true){String m=in.readUTF();SwingUtilities.invokeLater(()->handle(m));}}catch(Exception e){SwingUtilities.invokeLater(()->status.setText("Mất kết nối với server"));}});t.setDaemon(true);t.start();}catch(Exception e){JOptionPane.showMessageDialog(this,"Không kết nối được server: "+e.getMessage());System.exit(1);}}
 private void place(int r,int c){if(ready||placement.ready())return;if(!opponentConnected){status.setText("Đang chờ người chơi thứ hai...");return;}try{placement.place(r,c,horizontal);placements.add(r+","+c+","+(horizontal?"H":"V"));send("PLACE|"+r+"|"+c+"|"+(horizontal?"H":"V"));render();log.append("Đã đặt tàu dài "+Board.FLEET[placement.placed()-1]+". Tiếp theo dài "+(placement.nextLength()==0?"—":placement.nextLength())+"\n");if(placement.ready()&&JOptionPane.showConfirmDialog(this,"Đặt đủ tàu. Báo Ready?","Sẵn sàng",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION){ready=true;send("READY");status.setText("Đã sẵn sàng, chờ đối thủ...");}}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage());}}
 private String placementLayout(){// Reconstruct placement from occupied IDs by scanning orientation is not possible; keep clicks in list in place().
 return String.join(";",placements);}
 private final java.util.List<String> placements=new java.util.ArrayList<>();
 private void shoot(int r,int c){if(!mode.equals("PLAYING")||active!=player)return;send("SHOT|"+r+"|"+c);}
 private void send(String s){try{out.writeUTF(s);out.flush();}catch(Exception ignored){}}
 private void handle(String m){String[] x=m.split("\\|",-1);switch(x[0]){case "WELCOME"->{player=Integer.parseInt(x[1]);}case "INFO"->{opponentConnected=true;alert(x[1]);}case "START","TIME"->alert(x[1]);case "PLACE_OK"->log.append("Server đã xác nhận đặt tàu "+x[1]+"/4.\n");case "TURN"->{active=Integer.parseInt(x[1]);status.setText((active==player?"Đến lượt bạn":"Lượt của "+x[2])+" · còn "+x[3]+" giây");}case "ATTACK_RESULT"->{if(x[2].equals("MISS"))log.append(x[1]+" bắn trượt; lượt chuyển cho "+x[5]+".\n");}case "SUNK"->alert(x[1]+" đã đánh chìm một tàu của "+x[2]+"!");case "WIN"->alert("Người chiến thắng: "+x[1]+". "+x[2]+" đã hết tàu.");case "ERROR"->alert(x[1]);case "STATE"->{mode=x[1];active=Integer.parseInt(x[2]);ownState=x[4];enemyState=x[5];render();status.setText(mode.equals("PLAYING")?(active==player?"Đến lượt bạn · còn "+x[3]+" giây":"Đối thủ đang đi · còn "+x[3]+" giây"):ready?"Chờ cả hai Ready":"Đang đặt tàu · tàu tiếp theo dài "+placement.nextLength());}default->{}}}
 private void alert(String s){log.append(s+"\n");JDialog d=new JDialog(this,"Thông báo",true);JLabel l=new JLabel(s,SwingConstants.CENTER);l.setBorder(BorderFactory.createEmptyBorder(18,24,18,24));JButton ok=new JButton("OK");ok.addActionListener(e->d.dispose());d.add(l,BorderLayout.CENTER);d.add(ok,BorderLayout.SOUTH);d.pack();d.setLocationRelativeTo(this);Timer timer=new Timer(3000,e->d.dispose());timer.setRepeats(false);timer.start();d.setVisible(true);}
 private void render(){for(int r=0;r<6;r++)for(int c=0;c<6;c++){int i=r*6+c;String shownOwn=ready?ownState:placement.encode();own[r][c].setText(switch(shownOwn.charAt(i)){case '1'->"■";case '2'->"·";case '3'->"×";default->" ";});enemy[r][c].setText(switch(enemyState.charAt(i)){case '2'->"·";case '3'->"×";default->" ";});own[r][c].setBackground(null);enemy[r][c].setBackground(null);}}
}
